"""
    cointCounter is Variable to hold the number of coin
    will be used as counter initialize to zero for now """
def cash_coins(cents: Any) -> object {
    cointCounter = 0;
    while (cents >= 25) {
        cents -= 25;
        cointCounter += 1;
    }
    while (cents >= 10) {
        cents -= 10;
        cointCounter += 1;
    }
    while (cents >= 5) {
        cents -= 5;
        cointCounter += 1;
    }
    while (cents >= 1) {
        cents -= 1;
        cointCounter += 1;
    }
    return cointCounter;
}

